html:
{%= frappe.akwad_report.get_style_tag() %}

<div class="akwad-report">

{%= frappe.akwad_report.build_header({
	title: __("Statement of Accounts"),
	company: filters.company,
	period: __("{0} to {1}", [frappe.datetime.str_to_user(filters.from_date), frappe.datetime.str_to_user(filters.to_date)]),
	meta: [
		{ label: __("Account"), value: filters.account },
		{ label: __("Party"), value: filters.party_name || filters.party },
		{ label: __("Categorized By"), value: frappe.akwad_report.strip_prefix(filters.categorize_by, "Categorize by") },
		{ label: __("Currency"), value: filters.presentation_currency }
	]
}) %}

{% var extra_columns = frappe.akwad_report.get_extra_columns(print_settings.extra_columns, columns); %}
{% var column_count = 6 + (filters.show_remarks ? 1 : 0) + extra_columns.length; %}

<table class="akwad-report-table">
	<thead>
		<tr>
			<th style="width: 9.5em; text-align: left; white-space: nowrap;">{%= __("Date") %}</th>
			<th style="text-align: left;">{%= __("Particulars") %}</th>
			<th style="text-align: left;">{%= __("Party") %}</th>
			{% if (filters.show_remarks) { %}
				<th style="text-align: left;">{%= __("Remarks") %}</th>
			{% } %}
			{%= frappe.akwad_report.render_extra_headers(extra_columns) %}
			<th style="width: 9em; text-align: right;">{%= __("Debit") %}</th>
			<th style="width: 9em; text-align: right;">{%= __("Credit") %}</th>
			<th style="width: 9em; text-align: right;">{%= __("Balance") %}</th>
		</tr>
	</thead>
	<tbody>
		{% for (var i = 0, l = data.length; i < l; i++) { %}
			{% var row = data[i]; %}
			{% var is_entry = !!row.posting_date; %}
			{% var is_spacer = !is_entry && !row.account; %}
			{% var is_opening_row = !is_entry && row.account === "'" + __("Opening") + "'"; %}
			{% var is_total_row = !is_entry && row.account === "'" + __("Total") + "'"; %}
			{% var is_closing_row = !is_entry && row.account === "'" + __("Closing (Opening + Total)") + "'"; %}
			{% var row_class = is_entry ? "" : (is_closing_row ? "akwad-row-closing" : ((is_total_row || is_opening_row) ? "akwad-row-total" : "akwad-row-group")); %}

			{% if (is_spacer) { %}
				<tr><td colspan="{%= column_count %}" style="padding: 4px 0; border: none;">&nbsp;</td></tr>
			{% } else { %}
				<tr class="{%= row_class %}">

					<td class="text-left" style="white-space: nowrap;">
						{% if (is_entry) { %}
							{%= frappe.datetime.str_to_user(row.posting_date) %}
						{% } %}
					</td>

					<td class="text-left">
						{% if (is_entry) { %}
							<div>{%= row.voucher_type %} {%= row.voucher_no %}</div>
							{% if (!(filters.party || filters.account) && row.account) { %}
								<div class="text-muted">{%= row.account %}</div>
							{% } %}
							{% if (row.bill_no) { %}
								<div class="text-muted">{%= __("Supplier Invoice No") %}: {%= row.bill_no %}</div>
							{% } %}
						{% } else if (is_opening_row) { %}
							{%= __("Opening Balance") %}
						{% } else if (is_closing_row) { %}
							{%= __("Closing Balance") %}
						{% } else if (is_total_row) { %}
							{%= __("Period Total") %}
						{% } else { %}
							{%= row.account %}
						{% } %}
					</td>

					<td class="text-left">
						{% if (is_entry) { %}
							{%= row.party || row.against || "" %}
						{% } %}
					</td>

					{% if (filters.show_remarks) { %}
					<td class="text-left">
						{% if (is_entry && row.remarks && row.remarks != "No Remarks") { %}
							{%= row.remarks %}
						{% } %}
					</td>
					{% } %}

					{%= frappe.akwad_report.render_extra_cells(row, extra_columns, is_entry) %}

					<td class="text-right">
						{% if (is_entry) { %}
							{% if (row.debit) { %}{%= format_currency(row.debit, filters.presentation_currency) %}{% } %}
						{% } else if (!is_opening_row) { %}
							{% if (row.debit) { %}{%= format_currency(row.debit, filters.presentation_currency) %}{% } %}
						{% } %}
					</td>

					<td class="text-right">
						{% if (is_entry) { %}
							{% if (row.credit) { %}{%= format_currency(row.credit, filters.presentation_currency) %}{% } %}
						{% } else if (!is_opening_row) { %}
							{% if (row.credit) { %}{%= format_currency(row.credit, filters.presentation_currency) %}{% } %}
						{% } %}
					</td>

					<td class="text-right">
						{%= format_currency(row.balance, filters.presentation_currency) %}
						{% if (is_closing_row && row.balance) { %}
							{%= row.balance < 0 ? " Cr" : " Dr" %}
						{% } %}
					</td>

				</tr>
			{% } %}
		{% } %}
	</tbody>
</table>

{%= frappe.akwad_report.letterhead_footer(print_settings) %}

{%= frappe.akwad_report.footer() %}

</div>
